		result = &ToolResult{Status: ToolStatusSuccess}
		if it.AgentThreadID != "" {
			result.Agent = &ToolResultAgent{ID: it.AgentThreadID}
		}
	case codexitem.KindOther:
		return nil
	default:
		return nil
	}

